/**
 * TASK: Zoom with the mouse wheel, and clamp the result.
 *
 * Register a MouseWheelListener. Every event reports e.getWheelRotation():
 * a NEGATIVE number means the wheel turned away from the user (zoom IN) and
 * a positive number means it turned towards the user (zoom OUT). The value
 * can be more than one notch at a time.
 *
 * Each notch changes the zoom by 25 percentage points:
 *     zoom = zoom - 25 * e.getWheelRotation()
 * and the result is then CLAMPED to the range 50..300, so a big spin stops
 * at the limit instead of running past it.
 *
 * The zoom starts at 100. After every event set the label named "zoom" to
 * the current value followed by a percent sign, for example "125%".
 *
 * Example: rotation -1 -> 125, then rotation -10 would give 375 so it stops
 * at 300, then rotation +1 -> 275.
 *
 * No window is ever opened -- the tests build MouseWheelEvents by hand and
 * hand them straight to the registered listener.
 */
import javax.swing.JLabel;
import javax.swing.JPanel;

public class WheelZoomPanel extends JPanel {

    private final JLabel zoomLabel = new JLabel("100%");
    private int zoom = 100;

    public WheelZoomPanel() {
        zoomLabel.setName("zoom");
        add(zoomLabel);
        // TODO: addMouseWheelListener(...) -- adjust the zoom by 25 per notch,
        // TODO: clamp it to 50..300 and refresh the label
    }

    public int zoom() {
        // TODO: return the current zoom percentage
        return 0;
    }
}

