public class WheelZoomPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static void wheel(WheelZoomPanel panel, int notches) {
        java.awt.event.MouseWheelEvent event = new java.awt.event.MouseWheelEvent(panel,
                java.awt.event.MouseEvent.MOUSE_WHEEL, System.currentTimeMillis(), 0,
                10, 10, 0, false, java.awt.event.MouseWheelEvent.WHEEL_UNIT_SCROLL,
                1, notches);
        for (java.awt.event.MouseWheelListener listener : panel.getMouseWheelListeners()) {
            listener.mouseWheelMoved(event);
        }
    }

    public static void main(String[] args) {
        try {
            WheelZoomPanel panel = new WheelZoomPanel();
            java.awt.Component label = find(panel, "zoom");

            check("a MouseWheelListener is registered", true,
                    panel.getMouseWheelListeners().length >= 1);
            check("zoom starts at 100", 100, panel.zoom());
            check("label starts at 100%", "100%", textOf(label));

            wheel(panel, -1);
            check("one notch away from the user zooms in", 125, panel.zoom());
            check("label follows the zoom", "125%", textOf(label));

            wheel(panel, 2);
            check("two notches towards the user zoom out", 75, panel.zoom());

            wheel(panel, 4);
            check("zooming out stops at 50", 50, panel.zoom());

            wheel(panel, -20);
            check("zooming in stops at 300", 300, panel.zoom());
            check("label at the upper limit", "300%", textOf(label));

            wheel(panel, 1);
            check("the limit is not sticky", 275, panel.zoom());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

